/** @jest-environment node */

const fs = require('fs');
const path = require('path');
const os = require('os');
const Module = require('module');

jest.mock('../fetchTranslations');

const { fetchTranslations } = require('../fetchTranslations');
const {
  generateTranslations,
  parseArgs,
  resolveConfigPath,
  runCli,
} = require('../cli');

describe('parseArgs', () => {
  it('parses generate command and config path', () => {
    expect(parseArgs(['generate', '--config', 'src/i18n/translation.config.js'])).toEqual({
      command: 'generate',
      configPath: 'src/i18n/translation.config.js',
    });
  });

  it('returns unknown command when command is not generate', () => {
    expect(parseArgs(['unknown'])).toEqual({ command: 'unknown' });
  });

  it('returns null command when argv is empty', () => {
    expect(parseArgs([])).toEqual({ command: null });
  });

  it('returns null command when command is an empty string', () => {
    expect(parseArgs([''])).toEqual({ command: null });
  });

  it('returns generate without config path when flag is missing', () => {
    expect(parseArgs(['generate'])).toEqual({
      command: 'generate',
      configPath: null,
    });
  });

  it('returns generate without config path when flag has no value', () => {
    expect(parseArgs(['generate', '--config'])).toEqual({
      command: 'generate',
      configPath: null,
    });
  });
});

describe('resolveConfigPath', () => {
  let tmpDir;
  let originalCwd;

  beforeEach(() => {
    tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'tms-cli-resolve-'));
    originalCwd = process.cwd();
    process.chdir(tmpDir);

    const configDir = path.join(tmpDir, 'src/i18n');
    fs.mkdirSync(configDir, { recursive: true });
    fs.writeFileSync(
      path.join(configDir, 'translation.config.js'),
      'module.exports = {};'
    );
  });

  afterEach(() => {
    process.chdir(originalCwd);
    fs.rmSync(tmpDir, { recursive: true, force: true });
  });

  it('resolves a valid relative config path within cwd', () => {
    const resolved = resolveConfigPath('src/i18n/translation.config.js');

    expect(resolved).toBe(
      fs.realpathSync(path.join(tmpDir, 'src/i18n/translation.config.js'))
    );
  });

  it('resolves a valid absolute config path within cwd', () => {
    const absolutePath = path.join(tmpDir, 'src/i18n/translation.config.js');
    const resolved = resolveConfigPath(absolutePath);

    expect(resolved).toBe(fs.realpathSync(absolutePath));
  });

  it('rejects config paths outside cwd', () => {
    const outsideDir = fs.mkdtempSync(path.join(os.tmpdir(), 'tms-cli-outside-'));

    try {
      fs.writeFileSync(
        path.join(outsideDir, 'translation.config.js'),
        'module.exports = {};'
      );

      expect(() => resolveConfigPath(path.join(outsideDir, 'translation.config.js'))).toThrow(
        'Config path must be within the current working directory'
      );
    } finally {
      fs.rmSync(outsideDir, { recursive: true, force: true });
    }
  });

  it('rejects path traversal outside cwd', () => {
    const outsideDir = fs.mkdtempSync(path.join(os.tmpdir(), 'tms-cli-traverse-'));

    try {
      fs.writeFileSync(
        path.join(outsideDir, 'translation.config.js'),
        'module.exports = {};'
      );

      const traversalPath = path.join('..', path.basename(outsideDir), 'translation.config.js');

      expect(() => resolveConfigPath(traversalPath)).toThrow(
        'Config path must be within the current working directory'
      );
    } finally {
      fs.rmSync(outsideDir, { recursive: true, force: true });
    }
  });

  it('rejects config files with unexpected names', () => {
    fs.writeFileSync(path.join(tmpDir, 'other.config.js'), 'module.exports = {};');

    expect(() => resolveConfigPath('other.config.js')).toThrow(
      'Config file must be named translation.config.js'
    );
  });

  it('rejects missing config files', () => {
    expect(() => resolveConfigPath('src/missing/translation.config.js')).toThrow(
      'Config file not found'
    );
  });

  it('rejects empty config path', () => {
    expect(() => resolveConfigPath('')).toThrow('Config path is required');
  });

  it('rejects non-string config path', () => {
    expect(() => resolveConfigPath(null)).toThrow('Config path is required');
    expect(() => resolveConfigPath(undefined)).toThrow('Config path is required');
    expect(() => resolveConfigPath(123)).toThrow('Config path is required');
  });

  it('rejects config paths that are directories', () => {
    fs.mkdirSync(path.join(tmpDir, 'translation.config.js'));

    expect(() => resolveConfigPath('translation.config.js')).toThrow(
      'Config path must point to a file'
    );
  });

  it('rejects config files without a .js extension', () => {
    jest.spyOn(path, 'extname').mockReturnValue('.ts');

    expect(() => resolveConfigPath('src/i18n/translation.config.js')).toThrow(
      'Config file must be a .js file'
    );

    path.extname.mockRestore();
  });

  it('resolves config path at cwd root', () => {
    fs.writeFileSync(
      path.join(tmpDir, 'translation.config.js'),
      'module.exports = {};'
    );

    const resolved = resolveConfigPath('translation.config.js');

    expect(resolved).toBe(
      fs.realpathSync(path.join(tmpDir, 'translation.config.js'))
    );
  });
});

describe('generateTranslations', () => {
  let tmpDir;
  let configPath;
  let originalCwd;
  let logSpy;
  let warnSpy;
  let errorSpy;

  beforeEach(() => {
    tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'tms-cli-'));
    originalCwd = process.cwd();
    process.chdir(tmpDir);

    const configDir = path.join(tmpDir, 'src/i18n');
    fs.mkdirSync(configDir, { recursive: true });
    configPath = path.join(configDir, 'translation.config.js');
    fs.writeFileSync(
      configPath,
      `module.exports = {
        bearerToken: 'test-token',
        requestedTagIds: ['tag-1'],
        apiBaseUrl: 'https://api.applanga.com/v1/api',
        outputPath: '../../public/locales',
        queryParams: { app: 'app-id' },
      };`
    );

    logSpy = jest.spyOn(console, 'log').mockImplementation(() => {});
    warnSpy = jest.spyOn(console, 'warn').mockImplementation(() => {});
    errorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});
    jest.clearAllMocks();
  });

  afterEach(() => {
    process.chdir(originalCwd);
    fs.rmSync(tmpDir, { recursive: true, force: true });
    logSpy.mockRestore();
    warnSpy.mockRestore();
    errorSpy.mockRestore();
    delete process.env.APPLANGA_API_KEY;
    delete process.env.TRANSLATIONS_TARGET_ENV;
  });

  it('skips generation when API key is missing', async () => {
    fs.writeFileSync(
      configPath,
      `module.exports = {
        requestedTagIds: ['tag-1'],
        apiBaseUrl: 'https://api.applanga.com/v1/api',
        outputPath: '../../public/locales',
      };`
    );

    const result = await generateTranslations(configPath);

    expect(result).toEqual({ skipped: true });
    expect(fetchTranslations).not.toHaveBeenCalled();
  });

  it('skips generation when placeholder API key is used', async () => {
    fs.writeFileSync(
      configPath,
      `module.exports = {
        bearerToken: 'your_applanga_api_key_here',
        requestedTagIds: ['tag-1'],
        apiBaseUrl: 'https://api.applanga.com/v1/api',
        outputPath: '../../public/locales',
      };`
    );

    const result = await generateTranslations(configPath);

    expect(result).toEqual({ skipped: true });
  });

  it('uses APPLANGA_API_KEY from environment when config has no bearerToken', async () => {
    fs.writeFileSync(
      configPath,
      `module.exports = {
        requestedTagIds: ['tag-1'],
        apiBaseUrl: 'https://api.applanga.com/v1/api',
        outputPath: '../../public/locales',
      };`
    );
    process.env.APPLANGA_API_KEY = 'env-token';

    fetchTranslations.mockResolvedValue({
      data: {
        'en-US': {
          main: {
            entries: {
              'homePage.title': { v: 'Home' },
            },
          },
        },
      },
    });

    const result = await generateTranslations(configPath);

    expect(result).toEqual({ skipped: false, processedCount: 1 });
    expect(fetchTranslations).toHaveBeenCalledWith(
      expect.objectContaining({ bearerToken: 'env-token' })
    );
  });

  it('throws when requestedTagIds is missing', async () => {
    fs.writeFileSync(
      configPath,
      `module.exports = {
        bearerToken: 'test-token',
        apiBaseUrl: 'https://api.applanga.com/v1/api',
        outputPath: '../../public/locales',
      };`
    );

    await expect(generateTranslations(configPath)).rejects.toThrow(
      'config.requestedTagIds is required'
    );
  });

  it('generates translation files on success', async () => {
    fetchTranslations.mockResolvedValue({
      data: {
        'en-US': {
          main: {
            entries: {
              'homePage.title': { v: 'Home' },
            },
          },
        },
      },
    });

    const result = await generateTranslations(configPath);

    expect(result).toEqual({ skipped: false, processedCount: 1 });
    expect(
      fs.existsSync(path.join(tmpDir, 'public/locales/en-US.json'))
    ).toBe(true);
  });

  it('throws when API response has no languages', async () => {
    fetchTranslations.mockResolvedValue({ invalid: true });

    await expect(generateTranslations(configPath)).rejects.toThrow(
      'No translations found in API response'
    );
  });

  it('throws when no translation files are generated', async () => {
    fetchTranslations.mockResolvedValue({
      data: {
        'en-US': {},
      },
    });

    await expect(generateTranslations(configPath)).rejects.toThrow(
      'No translation files generated'
    );
  });

  it('logs release mode for prod environment', async () => {
    process.env.TRANSLATIONS_TARGET_ENV = 'prod';

    fetchTranslations.mockResolvedValue({
      data: {
        'en-US': {
          main: {
            entries: {
              'homePage.title': { v: 'Home' },
            },
          },
        },
      },
    });

    await generateTranslations(configPath);

    expect(logSpy).toHaveBeenCalledWith(expect.stringContaining('release (UAT/PROD: prefer .v)'));
  });

  it('loads dotenv when available', async () => {
    let dotenvAvailable = true;
    try {
      require.resolve('dotenv');
    } catch (error) {
      dotenvAvailable = false;
    }

    if (!dotenvAvailable) {
      return;
    }

    const envPath = path.join(tmpDir, '.env');
    fs.writeFileSync(envPath, 'APPLANGA_API_KEY=from-dotenv\n');

    fs.writeFileSync(
      configPath,
      `module.exports = {
        requestedTagIds: ['tag-1'],
        apiBaseUrl: 'https://api.applanga.com/v1/api',
        outputPath: '../../public/locales',
      };`
    );

    fetchTranslations.mockResolvedValue({
      data: {
        'en-US': {
          main: {
            entries: {
              'homePage.title': { v: 'Home' },
            },
          },
        },
      },
    });

    const result = await generateTranslations(configPath);

    expect(result).toEqual({ skipped: false, processedCount: 1 });
    expect(fetchTranslations).toHaveBeenCalledWith(
      expect.objectContaining({ bearerToken: 'from-dotenv' })
    );
  });

  it('continues when dotenv is unavailable', async () => {
    const originalLoad = Module._load;
    Module._load = function load(request, parent, isMain) {
      if (request === 'dotenv') {
        throw new Error('Cannot find module dotenv');
      }
      return originalLoad.call(this, request, parent, isMain);
    };

    fetchTranslations.mockResolvedValue({
      data: {
        'en-US': {
          main: {
            entries: {
              'homePage.title': { v: 'Home' },
            },
          },
        },
      },
    });

    await expect(generateTranslations(configPath)).resolves.toEqual({
      skipped: false,
      processedCount: 1,
    });

    Module._load = originalLoad;
  });
});

describe('runCli', () => {
  let exitSpy;
  let logSpy;
  let errorSpy;

  beforeEach(() => {
    exitSpy = jest.spyOn(process, 'exit').mockImplementation(() => {});
    logSpy = jest.spyOn(console, 'log').mockImplementation(() => {});
    errorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});
    fetchTranslations.mockReset();
  });

  afterEach(() => {
    exitSpy.mockRestore();
    logSpy.mockRestore();
    errorSpy.mockRestore();
  });

  it('prints usage and exits 0 when no command is provided', async () => {
    await runCli([]);

    expect(logSpy).toHaveBeenCalledWith(expect.stringContaining('Usage:'));
    expect(exitSpy).toHaveBeenCalledWith(0);
  });

  it('exits 1 for unknown commands', async () => {
    await runCli(['unknown']);

    expect(exitSpy).toHaveBeenCalledWith(1);
  });

  it('exits 1 when --config is missing', async () => {
    await runCli(['generate']);

    expect(errorSpy).toHaveBeenCalledWith('❌ Error: --config is required');
    expect(exitSpy).toHaveBeenCalledWith(1);
  });

  it('exits 1 when generation fails', async () => {
    const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'tms-runcli-'));
    const originalCwd = process.cwd();

    try {
      process.chdir(tmpDir);
      const configDir = path.join(tmpDir, 'src/i18n');
      fs.mkdirSync(configDir, { recursive: true });
      const configFile = path.join(configDir, 'translation.config.js');
      fs.writeFileSync(
        configFile,
        `module.exports = {
          bearerToken: 'test-token',
          apiBaseUrl: 'https://api.applanga.com/v1/api',
          outputPath: '../../public/locales',
        };`
      );

      await runCli(['generate', '--config', configFile]);

      expect(errorSpy).toHaveBeenCalledWith('\n❌ Error:', expect.any(String));
      expect(exitSpy).toHaveBeenCalledWith(1);
    } finally {
      process.chdir(originalCwd);
      fs.rmSync(tmpDir, { recursive: true, force: true });
    }
  });

  it('exits 0 after successful generation', async () => {
    const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'tms-runcli-ok-'));
    const originalCwd = process.cwd();

    try {
      process.chdir(tmpDir);
      const configDir = path.join(tmpDir, 'src/i18n');
      fs.mkdirSync(configDir, { recursive: true });
      const configFile = path.join(configDir, 'translation.config.js');
      fs.writeFileSync(
        configFile,
        `module.exports = {
          bearerToken: 'test-token',
          requestedTagIds: ['tag-1'],
          apiBaseUrl: 'https://api.applanga.com/v1/api',
          outputPath: '../../public/locales',
        };`
      );

      fetchTranslations.mockResolvedValue({
        data: {
          'en-US': {
            main: {
              entries: {
                'homePage.title': { v: 'Home' },
              },
            },
          },
        },
      });

      await runCli(['generate', '--config', configFile]);

      expect(exitSpy).toHaveBeenCalledWith(0);
    } finally {
      process.chdir(originalCwd);
      fs.rmSync(tmpDir, { recursive: true, force: true });
    }
  });

  it('exits 0 when generation is skipped', async () => {
    const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'tms-runcli-skip-'));
    const originalCwd = process.cwd();

    try {
      process.chdir(tmpDir);
      const configDir = path.join(tmpDir, 'src/i18n');
      fs.mkdirSync(configDir, { recursive: true });
      const configFile = path.join(configDir, 'translation.config.js');
      fs.writeFileSync(
        configFile,
        `module.exports = {
          requestedTagIds: ['tag-1'],
          apiBaseUrl: 'https://api.applanga.com/v1/api',
          outputPath: '../../public/locales',
        };`
      );

      await runCli(['generate', '--config', configFile]);

      expect(exitSpy).toHaveBeenCalledWith(0);
    } finally {
      process.chdir(originalCwd);
      fs.rmSync(tmpDir, { recursive: true, force: true });
    }
  });
});
